        return Integer.parseInt(d);
    }

    public int[] readArrayOfInt(int size, int indexFrom) throws IOException {
        int[] a = new int[size + indexFrom];
        String[] parts = br.readLine().split(" ");
        int ind = indexFrom;
        for (String item : parts) {
            a[ind++] = Integer.parseInt(item);
        }
        return a;
    }

    public String[] readArrayOfString(int size, int indexFrom) throws IOException {
        String[] a = new String[size + indexFrom];
        String[] parts = br.readLine().split(" ");
