class Utils {
    public static List<Integer> ntimes(int n, SupplierWithException<Integer> func, boolean returnResults) throws Exception {
        List<Integer> a = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            int result = func.get();
            if (returnResults) {
                a.add(result);
            }
        }
        return a;
    }

    public static void cumsum(Map<Integer, Integer> a) {
        int sum = 0;
        for (Map.Entry<Integer, Integer> e : a.entrySet()) {
            int k = e.getKey();
            int v = e.getValue();
            int nv = v + sum;
            a.put(k, nv);
            sum = nv;
        }
    }

    public static void diff(Map<Integer, Integer> a) {
        int prev = 0;
        for (Map.Entry<Integer, Integer> e : a.entrySet()) {
            int k = e.getKey();
            int v = e.getValue();
            int buf = v;
            a.put(k, v - prev);
            prev = buf;
        }
    }

    public static int bitCount(int n) {
        int cnt = 0;
        for (int j = n; j != 0; j >>= 1) {
            cnt += (j & 1);
        }
        return cnt;
    }

    interface SupplierWithException<T> {
        T get() throws Exception;
    }
}

class PrimeUtils {
    protected static Map<Integer, Map<Integer, Boolean>> divisors = new HashMap<>();
    protected static Map<Integer, Integer> primes = new HashMap<>();

    static {
        Map<Integer, Boolean> d1 = new HashMap<>();
        d1.put(1, true);
        divisors.put(1, d1);

        Map<Integer, Boolean> d2 = new HashMap<>();
        d2.put(1, true);
        d2.put(2, true);
        divisors.put(2, d2);
    }

    public static List<Integer> primes(int limit) {
        int len = (limit >> 3) + 1;
        byte[] a = new byte[len];
        Arrays.fill(a, (byte) 85);
        a[0] = 83;
        for (int i = 3; i * i < limit; i += 2) {
            if ((a[i >> 3] & (1 << (i % 8))) != 0) {
            } else {
                for (int k = i; k * i < limit; k++) {
                    int n = k * i;
                    a[n >> 3] = (byte) (a[n >> 3] | (1 << (n % 8)));
                }
            }
        }
        List<Integer> res = new ArrayList<>();
        res.add(2);
        for (int i = 3; i < limit; i += 2) {
            if ((a[i >> 3] & (1 << (i % 8))) == 0) {
                res.add(i);
            }
        }
        return res;
    }

    public static Map<Integer, Boolean> divisors(int n, int lp) {
        if (divisors.containsKey(n)) {
            return divisors.get(n);
        }
        if (primes.isEmpty()) {
            Map<Integer, Integer> ps = new HashMap<>();
            for (int prime : primes(1000)) {
                ps.put(prime, prime);
            }
            primes = ps;
        }
        Map<Integer, Boolean> r = new HashMap<>();
        for (int p : primes.keySet()) {
            if (p >= lp) {
                if (n < p * p) {
                    r.put(1, true);
                    r.put(n, true);
                    break;
                } else if (n % p == 0) {
                    int[] pres = {1, p};
                    Map<Integer, Boolean> sub = divisors(n / p, p);
                    for (int pre : pres) {
                        for (int nxt : sub.keySet()) {
                            r.put(nxt * pre, true);
                        }
                    }
                    break;
                }
            }
        }
        divisors.put(n, r);
        return divisors.get(n);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        InputReader ir = new InputReader(System.in);

        int[] nk = ir.readArrayOfInt(2, 0);
        int n = nk[0];
        int k = nk[1];

        List<Long> xs = new ArrayList<>();
        Map<Integer, Boolean> divs = PrimeUtils.divisors(n, 2);
        for (Map.Entry<Integer, Boolean> entry : divs.entrySet()) {
            int divisor = entry.getKey();
            int l = divisor;
            int m = n / l;
            if (m < k) {
                xs.add((long) k * l + m);
            }
        }

        if (xs.isEmpty()) {
            System.out.print((long) n * k + 1);
        } else {
            long min = xs.get(0);
            for (long v : xs) {
                if (v < min) min = v;
            }
            System.out.print(min);
        }
    }
}

